var i=`0722-funje`;var n=`world-0722`;var t=`AO`;var a=`central-africa`;var r=8;var o=48;var l={en:`Funje`,ua:`Фунже`};var d={en:`Funje is a Angola classic prepared with cassava flour. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Фунже, страва кухні країни Ангола зі складниками: борошно маніоку. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Cook the listed ingredients in simmering water for about 10 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 10 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:10,i:[[`water`,1200,`ml`],[`table-salt`,5,`g`]]},{en:`Add processed cassava flour slowly to boiling water, stirring strongly until the funje becomes a smooth, elastic paste.`,ua:`Повільно всипайте оброблене маніокове борошно в окріп, постійно енергійно помішуючи до гладкої еластичної фунже.`,t:[`absorption-cooking`],m:23,i:[[`cassava-flour`,420,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`red-palm-oil`,20,`ml`]]}];var u={slug:i,id:n,country:`AO`,region:a,servings:8,minutes:48,title:l,text:d,steps:g};export{t as country,u as default,n as id,o as minutes,a as region,r as servings,i as slug,g as steps,d as text,l as title};